using Microsoft.EntityFrameworkCore;using WhatsBiz.Application.Common.Interfaces;using WhatsBiz.Domain.Customers;namespace WhatsBiz.Infrastructure.Persistence;
public sealed class CustomerRepository(ApplicationDbContext db):ICustomerRepository{public async Task<(IReadOnlyCollection<Customer>,int)> Search(string? q,bool? active,string sort,bool desc,int page,int size,CancellationToken t){var x=db.Customers.AsNoTracking().Where(c=>!c.IsDeleted);if(!string.IsNullOrWhiteSpace(q))x=x.Where(c=>c.CustomerCode.Contains(q)||c.CustomerName.Contains(q)||(c.GSTIN!=null&&c.GSTIN.Contains(q))||(c.Mobile!=null&&c.Mobile.Contains(q)));if(active.HasValue)x=x.Where(c=>c.IsActive==active);x=desc?x.OrderByDescending(c=>c.CustomerName):x.OrderBy(c=>c.CustomerName);var n=await x.CountAsync(t);return(await x.Skip((page-1)*size).Take(size).ToArrayAsync(t),n);}public Task<Customer?> GetById(Guid id,bool tracking,CancellationToken t){var q=db.Customers.Include(x=>x.PaymentTerm).Include(x=>x.Contacts).Include(x=>x.Addresses).Include(x=>x.BankAccounts).Include(x=>x.Documents).Where(x=>!x.IsDeleted);if(!tracking)q=q.AsNoTracking();return q.SingleOrDefaultAsync(x=>x.CustomerId==id,t);}public Task<bool> Duplicate(string code,string? gst,string name,Guid? exclude,CancellationToken t)=>db.Customers.AnyAsync(x=>!x.IsDeleted&&(!exclude.HasValue||x.CustomerId!=exclude)&&(x.CustomerCode==code.Trim()||x.CustomerName==name.Trim()||(!string.IsNullOrWhiteSpace(gst)&&x.GSTIN==gst.Trim())),t);public async Task<IReadOnlyCollection<CustomerPaymentTerm>> Terms(CancellationToken t)=>await db.CustomerPaymentTerms.AsNoTracking().Where(x=>x.IsActive).OrderBy(x=>x.DueDays).ToArrayAsync(t);public void Add(Customer c)=>db.Customers.Add(c);public void RemoveChildren(Customer c){db.CustomerContacts.RemoveRange(c.Contacts);db.CustomerAddresses.RemoveRange(c.Addresses);db.CustomerBankAccounts.RemoveRange(c.BankAccounts);c.Contacts=[];c.Addresses=[];c.BankAccounts=[];}public Task<CustomerDocument?> Document(Guid cid,Guid did,bool tracking,CancellationToken t){var q=db.CustomerDocuments.Where(x=>x.CustomerId==cid&&x.DocumentId==did&&!x.IsDeleted);if(!tracking)q=q.AsNoTracking();return q.SingleOrDefaultAsync(t);}public void Add(CustomerDocument d)=>db.CustomerDocuments.Add(d);public Task Save(CancellationToken t)=>db.SaveChangesAsync(t);}
